/*
 * prog29_roman_numeral_parser.c
 *
 * The original binary implements a very small Roman‑numeral parser.
 * It accepts a single command‑line argument, converts it to upper case,
 * checks that it contains only the characters I V X L C D M,
 * parses it using the classic “largest‑value‑first” algorithm and
 * prints the resulting integer value.
 *
 * If the input is missing, longer than 63 characters, contains any
 * other character, does not represent a valid Roman numeral, or the
 * resulting value would be larger than 3999, the program prints
 * the literal string "INVALID".
 *
 * The implementation below reproduces exactly that observable
 * behaviour (stdout) while being clean, readable C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MAX_INPUT_LEN 63          /* 0x3f in the original code */
#define MAX_VALUE      3999       /* Upper bound checked in the binary */

/* Roman symbols in descending order together with their values.
 * The order matches the one used by the original state‑machine
 * (13 entries, index 0 … 12). */
static const char * const roman_sym[] = {
    "M",  "CM", "D",  "CD", "C",
    "XC", "L",  "XL", "X",  "IX",
    "V",  "IV", "I"
};

static const int roman_val[] = {
    1000, 900, 500, 400, 100,
     90,   50,  40,  10,   9,
      5,    4,   1
};

#define SYM_COUNT (sizeof(roman_sym)/sizeof(roman_sym[0]))

/* Returns 1 if c is a valid Roman numeral character, 0 otherwise. */
static int is_roman_char(char c)
{
    switch (c) {
        case 'I': case 'V': case 'X':
        case 'L': case 'C': case 'D':
        case 'M':
            return 1;
        default:
            return 0;
    }
}

/* Convert a string to upper case in‑place. */
static void strtoupper(char *s)
{
    for ( ; *s; ++s )
        *s = (char)toupper((unsigned char)*s);
}

/* Parse a Roman numeral that is already known to consist only of
 * the characters I V X L C D M and is at most 63 characters long.
 * Returns the integer value on success, -1 on failure (invalid
 * sequence or value > 3999). */
static int parse_roman(const char *s)
{
    int total = 0;
    size_t pos = 0;
    size_t len = strlen(s);

    for (size_t i = 0; i < SYM_COUNT; ++i) {
        const char *sym = roman_sym[i];
        size_t sym_len = strlen(sym);

        while (pos + sym_len <= len && strncmp(s + pos, sym, sym_len) == 0) {
            total += roman_val[i];
            pos   += sym_len;

            if (total > MAX_VALUE)          /* overflow check */
                return -1;
        }
    }

    return (pos == len) ? total : -1;       /* whole string must be consumed */
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    /* Make a mutable copy of the argument (the original program
     * stored the upper‑cased version in a buffer called main_upper). */
    char buf[64];               /* 63 chars + terminating NUL */
    size_t in_len = strlen(argv[1]);

    if (in_len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }

    strcpy(buf, argv[1]);
    strtoupper(buf);

    /* Verify that every character is a legal Roman numeral letter. */
    for (size_t i = 0; i < in_len; ++i) {
        if (!is_roman_char(buf[i])) {
            puts("INVALID");
            return 0;
        }
    }

    int value = parse_roman(buf);
    if (value < 0) {
        puts("INVALID");
    } else {
        printf("%d\n", value);
    }
    return 0;
}
